import json, re, sqlite3, threading, time
from .domain import Action, Condition, Incident, fp

SECRET = re.compile(r"sk_test_SYNTH_[\w-]+")


def redact(obj) -> str:
    return SECRET.sub(lambda m: fp(m.group()), json.dumps(obj, default=str))


class Store:
    def __init__(self, path="rook.db"):
        self.c = sqlite3.connect(path, check_same_thread=False)
        self.lock = threading.RLock()
        self._x("CREATE TABLE IF NOT EXISTS incidents(id TEXT PRIMARY KEY, data TEXT)")
        self._x("CREATE TABLE IF NOT EXISTS actions(id TEXT PRIMARY KEY, incident_id TEXT, seq INTEGER, data TEXT)")
        self._x("CREATE TABLE IF NOT EXISTS conditions(incident_id TEXT, id TEXT, seq INTEGER, data TEXT, PRIMARY KEY(incident_id,id))")
        self._x("CREATE TABLE IF NOT EXISTS audit(n INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, incident_id TEXT, event TEXT, data TEXT)")
        self._x("CREATE TABLE IF NOT EXISTS checkpoints(n INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, incident_id TEXT, label TEXT, data TEXT)")
        self._x("CREATE TABLE IF NOT EXISTS sandbox(id INTEGER PRIMARY KEY, data TEXT)")
        self._x("CREATE TRIGGER IF NOT EXISTS audit_no_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'audit is append-only'); END")
        self._x("CREATE TRIGGER IF NOT EXISTS audit_no_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'audit is append-only'); END")

    def _x(self, sql, args=()):
        with self.lock:
            cur = self.c.execute(sql, args)
            self.c.commit()
            return cur.fetchall()

    # sandbox state
    def load_sandbox(self):
        r = self._x("SELECT data FROM sandbox WHERE id=1")
        return json.loads(r[0][0]) if r else None

    def save_sandbox(self, s):
        self._x("INSERT OR REPLACE INTO sandbox(id,data) VALUES(1,?)", (json.dumps(s),))

    # incidents
    def save_incident(self, inc: Incident):
        self._x("INSERT OR REPLACE INTO incidents VALUES(?,?)", (inc.id, inc.model_dump_json()))

    def incident(self, iid) -> Incident:
        return Incident.model_validate_json(self._x("SELECT data FROM incidents WHERE id=?", (iid,))[0][0])

    def incidents(self):
        rows = self._x("SELECT data FROM incidents")
        return sorted((Incident.model_validate_json(r[0]) for r in rows), key=lambda i: -i.created_at)

    # actions
    def add_action(self, a: Action, seq: int):
        self._x("INSERT INTO actions VALUES(?,?,?,?)", (a.id, a.incident_id, seq, a.model_dump_json()))

    def save_action(self, a: Action):
        self._x("UPDATE actions SET data=? WHERE id=?", (a.model_dump_json(), a.id))

    def actions(self, iid):
        rows = self._x("SELECT data FROM actions WHERE incident_id=? ORDER BY seq", (iid,))
        return [Action.model_validate_json(r[0]) for r in rows]

    # closure conditions
    def save_conditions(self, iid, conds):
        for i, c in enumerate(conds):
            self._x("INSERT OR REPLACE INTO conditions(incident_id,id,seq,data) VALUES(?,?,?,?)",
                    (iid, c.id, i, c.model_dump_json()))

    def conditions(self, iid):
        rows = self._x("SELECT data FROM conditions WHERE incident_id=? ORDER BY seq", (iid,))
        return [Condition.model_validate_json(r[0]) for r in rows]

    # audit + checkpoints (secrets redacted before write)
    def audit(self, iid, event, data=None):
        self._x("INSERT INTO audit(ts,incident_id,event,data) VALUES(?,?,?,?)",
                (time.time(), iid, event, redact(data or {})))

    def audit_events(self, iid):
        return [{"n": r[0], "ts": r[1], "event": r[2], "data": json.loads(r[3])}
                for r in self._x("SELECT n,ts,event,data FROM audit WHERE incident_id=? ORDER BY n", (iid,))]

    def checkpoint(self, iid, label, data):
        self._x("INSERT INTO checkpoints(ts,incident_id,label,data) VALUES(?,?,?,?)",
                (time.time(), iid, label, redact(data)))

    def checkpoints(self, iid):
        return [{"n": r[0], "ts": r[1], "label": r[2], "data": json.loads(r[3])}
                for r in self._x("SELECT n,ts,label,data FROM checkpoints WHERE incident_id=? ORDER BY n", (iid,))]
"""Deterministic, model-independent authorization. Fails closed."""

ALLOWED = {
    "disable_account": {"github", "cloud", "pm"},
    "rotate_credential": {"vault"},
    "repair_config": {"app"},
}


def owner_of(sb, a):
    p = a.params
    try:
        if a.type == "disable_account":
            return sb.account_service(p["service"]).owner(a.target)
        if a.type == "rotate_credential":
            return sb.vault.owner(a.target)
        if a.type == "repair_config":
            return sb.vault.owner(p["cred_id"])
    except KeyError:
        return None


def decide(a, inc, sb, plan, approved=False):
    """Returns (authorized | needs_approval | blocked, reason)."""
    if a.type not in ALLOWED or a.params.get("service") not in ALLOWED[a.type]:
        return "blocked", "action/service outside approved policy"
    owner = owner_of(sb, a)
    if owner is None:
        return "blocked", "ownership cannot be established (fail closed)"
    if owner != inc.subject:
        return "blocked", f"target belongs to {owner}, not incident subject {inc.subject}"
    if a.type == "repair_config":
        if a.target not in sb.vault.used_by(a.params["cred_id"]):
            return "blocked", "app is not a dependent of this credential"
    if a.type == "rotate_credential":
        deps = set(sb.vault.used_by(a.target))
        have = {x.target for x in plan
                if x.type == "repair_config" and x.params.get("cred_id") == a.target}
        if deps - have:
            return "blocked", f"dependent apps without repair step: {sorted(deps - have)}"
        if len(deps) > 1 and not approved:
            return "needs_approval", f"credential shared by {len(deps)} apps (blast radius): human approval required"
    return "authorized", "approved by policy" + (" + human approval" if approved else "")

"""Independent verification. Observers read sandbox state only, never adapter responses."""
import time
from .domain import Condition


def _account_disabled(sb, a):
    st = sb.account_service(a["service"]).status(a["user"])
    return (None if st is None else st == "disabled"), {"observed_status": st}


def _credential_rejected(sb, a):
    accepted = sb.vault.accepts_fp(a["fp"])
    return (not accepted), {"old_fp": a["fp"], "old_credential_accepted": accepted}


def _replacement_accepted(sb, a):
    ver, acc = sb.vault.version(a["cred_id"]), sb.vault.accepts_current(a["cred_id"])
    return (ver > 1 and acc), {"vault_version": ver, "replacement_accepted": acc}


def _app_uses_replacement(sb, a):
    cfg, cur = sb.apps.config_fp(a["app"]), sb.vault.current_fp(a["cred_id"])
    ok = cfg == cur and cfg != a["old_fp"]
    return ok, {"app_config_fp": cfg, "vault_current_fp": cur}


def _app_healthy(sb, a):
    h = sb.apps.health(a["app"])
    return h, {"health_check_passed": h}


OBSERVERS = {
    "account_disabled": _account_disabled,
    "credential_rejected": _credential_rejected,
    "replacement_accepted": _replacement_accepted,
    "app_uses_replacement": _app_uses_replacement,
    "app_healthy": _app_healthy,
}


def observe(sb, method, args):
    try:
        return OBSERVERS[method](sb, args)
    except Exception as e:                       # missing/unobservable state => inconclusive
        return None, {"error": type(e).__name__}


def build_conditions(rel):
    conds = []
    for r in rel:
        if r["rel"] == "has_account":
            conds.append(Condition(
                id=f"{r['service']}-{r['user']}-disabled",
                description=f"Account {r['user']} on {r['service']} is disabled",
                expected="status == disabled", method="account_disabled",
                args={"service": r["service"], "user": r["user"]}))
        elif r["rel"] == "owns_credential" and r["status"] == "active":
            c = r["cred"]
            conds.append(Condition(
                id=f"{c}-old-rejected", description=f"Old credential {r['fp']} is rejected",
                expected="old fingerprint not accepted by vault", method="credential_rejected",
                args={"fp": r["fp"]}))
            conds.append(Condition(
                id=f"{c}-replacement-works", description=f"Replacement for {c} is issued and accepted",
                expected="version > 1 and active", method="replacement_accepted",
                args={"cred_id": c}))
            for app in r["used_by"]:
                conds.append(Condition(
                    id=f"{app}-uses-replacement", description=f"{app} is configured with the replacement",
                    expected="app config == vault current, != old", method="app_uses_replacement",
                    args={"app": app, "cred_id": c, "old_fp": r["fp"]}))
                conds.append(Condition(
                    id=f"{app}-healthy", description=f"{app} passes health/regression check",
                    expected="health check passes", method="app_healthy", args={"app": app}))
    return conds


def evaluate(sb, conds):
    out = []
    for c in conds:
        ok, ev = observe(sb, c.method, c.args)
        out.append(c.model_copy(update={"result": ok, "evidence": ev, "evaluated_at": time.time()}))
    return out


def _combine(results):
    ev = {}
    for _, e in results:
        ev.update(e)
    oks = [o for o, _ in results]
    if any(o is False for o in oks):
        return False, ev
    if any(o is None for o in oks):
        return None, ev
    return True, ev


def verify_action(sb, a):
    p = a.params
    if a.type == "disable_account":
        checks = [("account_disabled", {"service": p["service"], "user": a.target})]
    elif a.type == "rotate_credential":
        checks = [("credential_rejected", {"fp": p["old_fp"]}),
                  ("replacement_accepted", {"cred_id": a.target})]
    elif a.type == "repair_config":
        checks = [("app_uses_replacement", {"app": a.target, "cred_id": p["cred_id"], "old_fp": p["old_fp"]}),
                  ("app_healthy", {"app": a.target})]
    else:
        return None, {"error": "no verifier"}
    return _combine([observe(sb, m, args) for m, args in checks])
