"""Tracing. Always safe to call.

Every span is recorded locally (optional JSONL) and, when neatlogs is initialised, exported as a
neatlogs/OpenTelemetry span. Attributes are redacted before they leave the process: synthetic
secret values are replaced by fingerprints and attribute keys that look sensitive are dropped.
"""
import contextlib, json, os, pathlib, re, time
from .store import redact

_hooks = []
_neatlogs = None          # the neatlogs module once init_neatlogs() succeeded

# span name prefix -> neatlogs span kind
KINDS = [
    ("incident.run", "WORKFLOW"), ("incident.start", "WORKFLOW"), ("demo.", "WORKFLOW"),
    ("plan", "AGENT"), ("investigate", "AGENT"), ("discover", "RETRIEVER"),
    ("policy", "GUARDRAIL"), ("approval", "GUARDRAIL"), ("verify", "GUARDRAIL"),
    ("closure", "GUARDRAIL"), ("probe", "GUARDRAIL"),
    ("execute", "TOOL"), ("adapter", "TOOL"), ("reconcile", "CHAIN"), ("checkpoint", "CHAIN"),
]
SENSITIVE_KEY = re.compile(r"(secret|token|password|authorization|api[_-]?key|value)", re.I)


def kind_for(name):
    for prefix, kind in KINDS:
        if name.startswith(prefix):
            return kind
    return "CHAIN"


def safe_attrs(attrs):
    """Redacted, flat, non-sensitive attributes suitable for export."""
    out = {}
    for k, v in json.loads(redact(attrs)).items():
        if SENSITIVE_KEY.search(k):
            continue
        out[f"rook.{k}"] = v if isinstance(v, (str, int, float, bool)) else json.dumps(v)
    return out


def init_neatlogs(workflow_name="rook-incident-response", tracer_provider=None, **kw):
    """Initialise neatlogs if an API key is configured (or a tracer provider is supplied for tests).

    Returns True when spans will be recorded through neatlogs.
    """
    global _neatlogs
    key = os.getenv("NEATLOGS_API_KEY")
    if not key and tracer_provider is None:
        return False
    import neatlogs
    args = dict(api_key=key or "local-test", workflow_name=workflow_name,
                tags=["keywarden", "rook", "sandbox"], user_id="svc-rook")
    if os.getenv("NEATLOGS_ENDPOINT"):
        args["endpoint"] = os.environ["NEATLOGS_ENDPOINT"]
    if tracer_provider is not None:
        args.update(tracer_provider=tracer_provider, disable_export=True,
                    register_shutdown_handlers=False)
    args.update(kw)
    neatlogs.init(**args)
    _neatlogs = neatlogs
    return True


def flush():
    if _neatlogs is not None:
        _neatlogs.flush()


def shutdown():
    global _neatlogs
    if _neatlogs is not None:
        _neatlogs.flush()
        _neatlogs.shutdown()
        _neatlogs = None


def delivery():
    return _neatlogs.get_delivery_diagnostics() if _neatlogs is not None else {}


def register_hook(fn):
    """fn(record: dict) is called for every finished span. Records are already redacted."""
    _hooks.append(fn)


class _Span:
    """Handle yielded by span(); lets callers attach results discovered inside the span."""
    def __init__(self, otel):
        self.otel, self.attrs = otel, {}

    def set(self, **attrs):
        self.attrs.update(attrs)
        if self.otel is not None:
            for k, v in safe_attrs(attrs).items():
                self.otel.set_attribute(k, v)

\[email]
def span(name, **attrs):
    t0 = time.time()
    err = None
    cm = _neatlogs.trace(name, kind=kind_for(name)) if _neatlogs is not None else contextlib.nullcontext()
    with cm as otel:
        h = _Span(otel)
        h.set(**attrs)
        try:
            yield h
        except BaseException as e:
            err = type(e).__name__
            if otel is not None:
                from opentelemetry.trace import Status, StatusCode
                otel.set_attribute("rook.error", err)
                otel.set_status(Status(StatusCode.ERROR, err))
            raise
        finally:
            rec = {"name": name, "ts": t0, "duration_ms": round((time.time() - t0) * 1000, 2),
                   "attrs": {**attrs, **h.attrs}, "error": err}
            line = redact(rec)
            if os.getenv("ROOK_TRACE"):
                d = pathlib.Path(os.getenv("ROOK_TRACE_DIR", "traces"))
                d.mkdir(parents=True, exist_ok=True)
                with open(d / "rook-trace.jsonl", "a") as f:
                    f.write(line + "\n")
            for fn in _hooks:
                try:
                    fn(json.loads(line))
                except Exception:
                    pass            # observability must never break remediation

"""Five stateful SANDBOXED MOCK adapters over one persisted local state.

Nothing here talks to a real system. All credentials are synthetic (sk_test_SYNTH_*).
Every state change goes through Sandbox.mutate(), which provides idempotency and
deterministic failure injection so recovery paths can be demonstrated and tested.
"""
import copy
from .domain import fp


class Transient(Exception): ...
class Permanent(Exception): ...
class Timeout(Exception): ...


OLD = "sk_test_SYNTH_payments_v1"
REPORTS = "sk_test_SYNTH_reports_v1"

# name -> (description, failures, flags). Failures are consumed in order per operation.
SCENARIOS = {
    "signature": ("billing-app's config API returns a 503 once while Rook moves it to the new key",
                  {"app.update_config": ["transient"]}, {}),
    "clean": ("No injected faults", {}, {}),
    "ambiguous_applied": ("payments-worker update times out but was actually applied",
                          {"cloud.update_env": ["timeout_applied"]}, {}),
    "ambiguous_lost": ("payments-worker update times out and was not applied",
                       {"cloud.update_env": ["timeout_lost"]}, {}),
    "persistent": ("billing-app's config API keeps failing", {"app.update_config": ["transient"] * 20}, {}),
    "permission_denied": ("Cloud refuses to disable the leftover account",
                          {"disable:cloud": ["permanent"]}, {}),
    "revoke_noop": ("Vault reports the old key revoked but it still works", {}, {"revoke_noop": True}),
    "replacement_invalid": ("Vault issues a replacement key that does not work", {}, {"replacement_invalid": True}),
    "faulty_update": ("billing-app accepts the update but stores the wrong key", {}, {"faulty_update": ["app:billing-app"]}),
    "regression_fail": ("billing-app is healthy but its payment regression test fails", {},
                        {"regression_fail": ["app:billing-app"]}),
}


def seed() -> dict:
    return {
        "directory": {   # identity provider, read via the internal app
            "ident-jdoe": {"name": "Jordan Doe", "type": "contractor", "employer": "Northwind Consulting",
                           "status": "disabled", "disabled_at": "2026-10-09T17:30:00Z", "manager": "ident-asmith"},
            "ident-asmith": {"name": "Alex Smith", "type": "employee", "status": "active"},
        },
        "github": {
            "accounts": {"jdoe": {"status": "disabled", "owner": "ident-jdoe"},
                         "asmith": {"status": "active", "owner": "ident-asmith"}},
            "repos": {"billing-api": {".env.test": f"PAYMENTS_KEY={OLD}", "README.md": "billing api"}},
            "audit_log": [{"event": "file_committed", "repo": "billing-api", "path": ".env.test",
                           "actor": "jdoe", "at": "2026-06-02T11:04:00Z"}],
        },
        "cloud": {
            "accounts": {"jdoe": {"status": "active", "owner": "ident-jdoe"},
                         "asmith": {"status": "active", "owner": "ident-asmith"}},
            "services": {"payments-worker": {"env": {"PAYMENTS_KEY": OLD}, "team": "payments"},
                         "reports-cron": {"env": {"REPORTS_KEY": REPORTS}, "team": "analytics"}},
        },
        "pm": {
            "accounts": {"jdoe": {"status": "active", "owner": "ident-jdoe"},
                         "ghost": {"status": "active", "owner": None}},     # orphaned account fixture
            "tickets": {"OPS-112": {"title": "Offboard contractor Jordan Doe", "status": "done",
                                    "subject": "ident-jdoe", "comments": []}},
            "next_ticket": 200,
        },
        "vault": {"credentials": {
            "cred-pay": {"owner": "ident-jdoe", "purpose": "Payments provider API key",
                         "created_by": "jdoe", "created_at": "2026-03-14T09:12:00Z",
                         "versions": [{"v": 1, "value": OLD, "status": "active"}],
                         # vault metadata is incomplete on purpose: payments-worker is only found by scanning
                         "used_by": ["app:billing-app"]},
            "cred-reports": {"owner": "ident-asmith", "purpose": "Reporting warehouse key",
                             "created_by": "asmith", "created_at": "2026-01-05T10:00:00Z",
                             "versions": [{"v": 1, "value": REPORTS, "status": "active"}],
                             "used_by": ["app:reports-app", "cloud:reports-cron"]},
        }},
        "apps": {"billing-app": {"config": {"PAYMENTS_KEY": OLD}},
                 "reports-app": {"config": {"REPORTS_KEY": REPORTS}}},
        "failures": {}, "flags": {}, "applied": {}, "calls": 0, "mutations": 0,
    }


class Adapter:
    def __init__(self, core):
        self.core = core

    @property
    def s(self):
        return self.core.s


class AccountService(Adapter):
    """Accounts on github (source host), cloud and pm share this behaviour."""
    def __init__(self, core, name):
        super().__init__(core)
        self.name = name

    def accounts(self):
        return self.s[self.name]["accounts"]

    def status(self, user):
        return self.accounts().get(user, {}).get("status")

    def owner(self, user):
        return self.accounts().get(user, {}).get("owner")

    def disable(self, user, idem):
        def fn():
            self.accounts()[user]["status"] = "disabled"
            return {"service": self.name, "user": user, "status": "disabled"}
        return self.core.mutate(f"disable:{self.name}", idem, fn)


class SourceHost(AccountService):
    """Adapter 1: source-code host."""
    def find_secret(self, f):
        """Paths of files containing a secret with fingerprint f. Values never leave this method."""
        out = []
        for repo, files in self.s["github"]["repos"].items():
            for path, txt in files.items():
                for token in txt.replace("=", " ").split():
                    if token.startswith("sk_test_SYNTH") and fp(token) == f:
                        out.append(f"{repo}/{path}")
        return out

    def commit_history(self, path):
        repo, file = path.split("/", 1)
        return [e for e in self.s["github"]["audit_log"] if e["repo"] == repo and e["path"] == file]


class Cloud(AccountService):
    """Adapter 2: cloud environment (accounts + services with environment variables)."""
    def services(self):
        return self.s["cloud"]["services"]

    def env_fps(self, svc):
        return {k: fp(v) for k, v in self.services()[svc]["env"].items()}

    def set_secret_env(self, svc, cred_id, idem):
        def fn():
            env = self.services()[svc]["env"]
            key = next(k for k, v in env.items() if v.startswith("sk_test_SYNTH"))
            env[key] = self.core.vault.latest(cred_id)["value"]
            if svc in self.s["flags"].get("faulty_update", []) or f"cloud:{svc}" in self.s["flags"].get("faulty_update", []):
                env[key] = "sk_test_SYNTH_wrong"
            return {"dependent": f"cloud:{svc}", "env_key": key, "config_fp": fp(env[key])}
        return self.core.mutate("cloud.update_env", idem, fn)


class InternalApp(Adapter):
    """Adapter 3: internal application (config, health, regression suite) + identity directory."""
    def directory(self, ident):
        return dict(self.s["directory"].get(ident, {}))

    def apps(self):
        return self.s["apps"]

    def config_fps(self, app):
        return {k: fp(v) for k, v in self.apps()[app]["config"].items()}

    def set_secret_config(self, app, cred_id, idem):
        def fn():
            cfg = self.apps()[app]["config"]
            key = next(k for k, v in cfg.items() if v.startswith("sk_test_SYNTH"))
            cfg[key] = self.core.vault.latest(cred_id)["value"]
            if f"app:{app}" in self.s["flags"].get("faulty_update", []):
                cfg[key] = "sk_test_SYNTH_wrong"
            return {"dependent": f"app:{app}", "config_key": key, "config_fp": fp(cfg[key])}
        return self.core.mutate("app.update_config", idem, fn)


class ProjectTracker(Adapter):
    """Adapter 4: project-management system (offboarding tickets, incident tickets)."""
    def tickets(self):
        return self.s["pm"]["tickets"]

    def completed_offboardings(self):
        return {tid: t for tid, t in self.tickets().items()
                if t.get("subject") and t["status"] == "done" and t["title"].startswith("Offboard")}

    def open_ticket(self, title, subject, idem):
        def fn():
            n = self.s["pm"]["next_ticket"]
            self.s["pm"]["next_ticket"] += 1
            tid = f"SEC-{n}"
            self.tickets()[tid] = {"title": title, "status": "open", "subject": subject, "comments": []}
            return {"ticket": tid}
        return self.core.mutate("pm.open_ticket", idem, fn)

    def comment(self, tid, text, idem):
        def fn():
            self.tickets()[tid]["comments"].append(text)
            return {"ticket": tid}
        return self.core.mutate("pm.comment", idem, fn)

    def set_status(self, tid, status, idem):
        def fn():
            self.tickets()[tid]["status"] = status
            return {"ticket": tid, "status": status}
        return self.core.mutate("pm.set_status", idem, fn)


class Vault(Adapter):
    """Adapter 5: credential vault with versioned secrets."""
    def creds(self):
        return self.s["vault"]["credentials"]

    def meta(self, cid):
        c = self.creds().get(cid)
        if c is None:
            return None
        return {k: v for k, v in c.items() if k != "versions"} | {
            "versions": [{"v": x["v"], "status": x["status"], "fp": fp(x["value"])} for x in c["versions"]]}

    def owner(self, cid):
        return self.creds().get(cid, {}).get("owner")

    def latest(self, cid):
        return self.creds()[cid]["versions"][-1]

    def version_info(self, cid, v):
        x = next((x for x in self.creds()[cid]["versions"] if x["v"] == v), None)
        return None if x is None else {"v": x["v"], "status": x["status"], "fp": fp(x["value"])}

    def authenticate_fp(self, f):
        """Live probe: would a request signed with the key of fingerprint f be accepted?"""
        if f in self.s["flags"].get("_noop_revoked", []):
            return True
        return any(x["status"] == "active" and fp(x["value"]) == f
                   for c in self.creds().values() for x in c["versions"])

    def find_by_fp(self, f):
        return next((cid for cid, c in self.creds().items() for x in c["versions"] if fp(x["value"]) == f), None)

    def issue_replacement(self, cid, idem):
        def fn():
            c = self.creds()[cid]
            v = c["versions"][-1]["v"] + 1
            status = "invalid" if self.s["flags"].get("replacement_invalid") else "active"
            c["versions"].append({"v": v, "value": f"sk_test_SYNTH_{cid}_v{v}", "status": status})
            return {"cred": cid, "version": v, "new_fp": fp(c["versions"][-1]["value"])}
        return self.core.mutate("vault.issue", idem, fn)

    def revoke(self, cid, version, idem):
        def fn():
            x = next(x for x in self.creds()[cid]["versions"] if x["v"] == version)
            if self.s["flags"].get("revoke_noop"):         # reports success, key keeps working
                self.s["flags"].setdefault("_noop_revoked", []).append(fp(x["value"]))
            x["status"] = "revoked"
            return {"cred": cid, "version": version, "status": "revoked"}
        return self.core.mutate("vault.revoke", idem, fn)


class Sandbox:
    def __init__(self, store, failures=None, flags=None, scenario=None):
        self.store = store
        s = store.load_sandbox()
        if s is None or scenario is not None:
            s = self._seeded(failures, flags, scenario)
            store.save_sandbox(s)
        self.s = s
        self.github = SourceHost(self, "github")
        self.cloud = Cloud(self, "cloud")
        self.pm = ProjectTracker(self)
        self.pm_accounts = AccountService(self, "pm")
        self.vault = Vault(self)
        self.apps = InternalApp(self)

    @staticmethod
    def _seeded(failures=None, flags=None, scenario=None):
        s = seed()
        if scenario is not None:
            _, f, fl = SCENARIOS[scenario]
            s["failures"], s["flags"] = copy.deepcopy(f), copy.deepcopy(fl)
            s["scenario"] = scenario
        if failures is not None:
            s["failures"] = failures
        if flags is not None:
            s["flags"] = flags
        return s

    def account_service(self, name):
        return {"github": self.github, "cloud": self.cloud, "pm": self.pm_accounts}[name]

    def reset(self, failures=None, flags=None, scenario=None):
        self.s = self._seeded(failures, flags, scenario)
        self._save()

    def reload(self):
        s = self.store.load_sandbox()
        if s is not None:
            self.s = s

    def _save(self):
        self.store.save_sandbox(self.s)

    # ---- dependents: anything configured with a credential, found by scanning live config ----
    def dependents_of_fp(self, f):
        deps = []
        for app in sorted(self.apps.apps()):
            if f in self.apps.config_fps(app).values():
                deps.append(f"app:{app}")
        for svc in sorted(self.cloud.services()):
            if f in self.cloud.env_fps(svc).values():
                deps.append(f"cloud:{svc}")
        return deps

    def dependent_config_fp(self, dep):
        kind, name = dep.split(":", 1)
        fps = self.apps.config_fps(name) if kind == "app" else self.cloud.env_fps(name)
        return next(iter(fps.values()), None)

    def update_dependent(self, dep, cred_id, idem):
        kind, name = dep.split(":", 1)
        if kind == "app":
            return self.apps.set_secret_config(name, cred_id, idem)
        if kind == "cloud":
            return self.cloud.set_secret_env(name, cred_id, idem)
        raise Permanent(f"unknown dependent kind {kind}")

    def health(self, dep):
        """Health probe: the dependent's configured key authenticates and the service is up."""
        f = self.dependent_config_fp(dep)
        return bool(f and self.vault.authenticate_fp(f) and dep not in self.s["flags"].get("unhealthy", []))

    def regression(self, dep):
        """Regression suite (e.g. a synthetic test charge for billing-app)."""
        return self.health(dep) and dep not in self.s["flags"].get("regression_fail", [])

    def mutate(self, op, idem, fn):
        """Idempotency + deterministic failure injection for every state change."""
        self.s["calls"] += 1
        if idem in self.s["applied"]:
            self._save()
            return {**self.s["applied"][idem], "replayed": True}
        q = self.s["failures"].get(op) or []
        kind = q.pop(0) if q else None
        if kind == "transient":
            self._save(); raise Transient(f"{op}: 503 service unavailable")
        if kind == "permanent":
            self._save(); raise Permanent(f"{op}: permission denied")
        if kind == "timeout_lost":        # request lost, nothing applied
            self._save(); raise Timeout(op)
        res = fn()
        self.s["mutations"] += 1
        self.s["applied"][idem] = res
        self._save()
        if kind == "timeout_applied":     # applied, but the caller never saw the response
            raise Timeout(op)
        return res

"""Independent verification.

Observers re-read sandbox state through probes (authentication, health, regression, config
fingerprints). They never look at what an adapter call returned, so a mutation that reports
success without changing state fails verification.
"""
import time
from .domain import Condition


def _account_disabled(sb, a):
    st = sb.account_service(a["service"]).status(a["user"])
    return (None if st is None else st == "disabled"), {"observed_status": st}


def _old_rejected(sb, a):
    accepted = sb.vault.authenticate_fp(a["fp"])
    return (not accepted), {"old_fp": a["fp"], "old_key_authenticates": accepted}


def _replacement_works(sb, a):
    latest = sb.vault.version_info(a["cred_id"], sb.vault.latest(a["cred_id"])["v"])
    ok = latest["v"] > a["old_version"] and sb.vault.authenticate_fp(latest["fp"])
    return ok, {"latest_version": latest["v"], "latest_fp": latest["fp"], "replacement_authenticates": ok}


def _dependent_uses_replacement(sb, a):
    cfg = sb.dependent_config_fp(a["dependent"])
    cur = sb.vault.version_info(a["cred_id"], sb.vault.latest(a["cred_id"])["v"])["fp"]
    ok = cfg == cur and cfg != a["old_fp"]
    return ok, {"dependent_config_fp": cfg, "vault_latest_fp": cur}


def _dependent_healthy(sb, a):
    h = sb.health(a["dependent"])
    return h, {"health_check_passed": h}


def _regression_passes(sb, a):
    r = sb.regression(a["dependent"])
    return r, {"regression_suite_passed": r}


def _no_live_dependents_on_old(sb, a):
    deps = sb.dependents_of_fp(a["fp"])
    return (not deps), {"still_configured_with_old_key": deps}


OBSERVERS = {
    "account_disabled": _account_disabled,
    "old_credential_rejected": _old_rejected,
    "replacement_works": _replacement_works,
    "dependent_uses_replacement": _dependent_uses_replacement,
    "dependent_healthy": _dependent_healthy,
    "regression_passes": _regression_passes,
    "no_dependents_on_old_key": _no_live_dependents_on_old,
}


def observe(sb, method, args):
    try:
        return OBSERVERS[method](sb, args)
    except Exception as e:                       # missing/unobservable state => inconclusive
        return None, {"error": type(e).__name__}


def build_conditions(rel):
    conds = []
    for r in rel:
        if r["rel"] == "has_account":
            conds.append(Condition(
                id=f"{r['service']}-{r['user']}-disabled",
                description=f"{r['service']} account '{r['user']}' is disabled",
                expected="account status is disabled", method="account_disabled",
                args={"service": r["service"], "user": r["user"]}))
        elif r["rel"] == "owns_credential" and r["status"] == "active":
            c = r["cred"]
            conds.append(Condition(
                id=f"{c}-old-rejected", description=f"The old key {r['fp']} is rejected when used",
                expected="authentication with the old key fails", method="old_credential_rejected",
                args={"fp": r["fp"]}))
            conds.append(Condition(
                id=f"{c}-replacement-works", description=f"A replacement for {c} is issued and accepted",
                expected="newer version exists and authenticates", method="replacement_works",
                args={"cred_id": c, "old_version": r["version"]}))
            conds.append(Condition(
                id=f"{c}-no-dependents-on-old", description="Nothing is still configured with the old key",
                expected="config scan finds no use of the old key", method="no_dependents_on_old_key",
                args={"fp": r["fp"]}))
            for dep in r["dependents"]:
                conds.append(Condition(
                    id=f"{dep}-uses-replacement", description=f"{dep} is configured with the replacement key",
                    expected="config fingerprint == vault latest, != old", method="dependent_uses_replacement",
                    args={"dependent": dep, "cred_id": c, "old_fp": r["fp"]}))
                conds.append(Condition(
                    id=f"{dep}-healthy", description=f"{dep} passes its health check",
                    expected="health probe passes", method="dependent_healthy", args={"dependent": dep}))
                conds.append(Condition(
                    id=f"{dep}-regression", description=f"{dep} passes its regression tests",
                    expected="regression suite passes", method="regression_passes", args={"dependent": dep}))
    return conds


def evaluate(sb, conds):
    out = []
    for c in conds:
        ok, ev = observe(sb, c.method, c.args)
        out.append(c.model_copy(update={"result": ok, "evidence": ev, "evaluated_at": time.time()}))
    return out


def _combine(results):
    ev = {}
    for _, e in results:
        ev.update(e)
    oks = [o for o, _ in results]
    if any(o is False for o in oks):
        return False, ev
    if any(o is None for o in oks):
        return None, ev
    return True, ev


def checks_for(a):
    p = a.params
    if a.type == "disable_account":
        return [("account_disabled", {"service": p["service"], "user": a.target})]
    if a.type == "issue_replacement":
        return [("replacement_works", {"cred_id": a.target, "old_version": p["old_version"]})]
    if a.type == "update_dependent":
        return [("dependent_uses_replacement", {"dependent": a.target, "cred_id": p["cred_id"], "old_fp": p["old_fp"]}),
                ("dependent_healthy", {"dependent": a.target})]
    if a.type == "revoke_credential":
        return [("old_credential_rejected", {"fp": p["old_fp"]})]
    return None


def verify_action(sb, a):
    """True = state shows the action took effect; False = it did not; None = cannot tell."""
    checks = checks_for(a)
    if checks is None:
        return None, {"error": "no verifier"}
    return _combine([observe(sb, m, args) for m, args in checks])


def applied(sb, a):
    """Reconciliation probe after an ambiguous outcome: did the mutation land at all?

    Narrower than verify_action: an applied-but-broken change must not be re-sent blindly.
    """
    p = a.params
    try:
        if a.type == "disable_account":
            return sb.account_service(p["service"]).status(a.target) == "disabled"
        if a.type == "issue_replacement":
            return sb.vault.latest(a.target)["v"] > p["old_version"]
        if a.type == "update_dependent":
            return sb.dependent_config_fp(a.target) != p["old_fp"]
        if a.type == "revoke_credential":
            return sb.vault.version_info(p["cred_id"], p["version"])["status"] == "revoked"
    except Exception:
        return None
    return None

"""Deterministic, model-independent authorization. Fails closed.

Rook runs as a least-privilege service principal: it may only perform the action types in
ALLOWED, only against the incident subject's own resources, and irreversible actions need a
human approver from the incident's organisation. Policy is evaluated when the plan is made
and again immediately before each action executes, against live state.
"""

ROOK_PRINCIPAL = "svc-rook"

ALLOWED = {
    "disable_account": {"github", "cloud", "pm"},
    "issue_replacement": {"vault"},
    "update_dependent": {"app", "cloud"},
    "revoke_credential": {"vault"},
}
NEEDS_APPROVAL = {"revoke_credential"}     # irreversible and production-affecting


def owner_of(sb, a):
    p = a.params
    try:
        if a.type == "disable_account":
            return sb.account_service(p["service"]).owner(a.target)
        if a.type in ("issue_replacement", "revoke_credential"):
            return sb.vault.owner(a.target)
        if a.type == "update_dependent":
            return sb.vault.owner(p["cred_id"])
    except KeyError:
        return None


def decide(a, inc, sb, plan, approval=None):
    """Returns (authorized | needs_approval | blocked, reason, rule)."""
    if a.type not in ALLOWED or a.params.get("service") not in ALLOWED[a.type]:
        return "blocked", "This action or service is outside what Rook is allowed to do.", "R1-allowlist"
    owner = owner_of(sb, a)
    if owner is None:
        return "blocked", "Rook could not confirm who owns this resource, so it will not touch it.", "R2-ownership"
    if owner != inc.subject:
        return "blocked", f"This resource belongs to {owner}, not to {inc.subject}.", "R2-ownership"

    if a.type == "update_dependent":
        live = sb.dependents_of_fp(a.params["old_fp"])
        if a.target not in live and not _already_moved(sb, a):
            return "blocked", f"{a.target} does not use this credential.", "R3-dependency"
    if a.type == "revoke_credential":
        live = set(sb.dependents_of_fp(a.params["old_fp"]))
        covered = {x.target for x in plan if x.type == "update_dependent"
                   and x.params.get("cred_id") == a.target and x.status.value != "blocked"}
        if live - covered:
            return ("blocked", "Revoking now would break " + ", ".join(sorted(live - covered))
                    + ", which still use the old key and have no update step.", "R4-safe-order")
        if a.params.get("version") == sb.vault.latest(a.target)["v"]:
            return "blocked", "Refusing to revoke the newest key version.", "R4-safe-order"

    if a.type in NEEDS_APPROVAL:
        if approval is None:
            return ("needs_approval", "Revoking a key cannot be undone, so a person with approver "
                    "rights must confirm it.", "R5-approval")
        if "approver" not in approval.get("roles", []) or approval.get("org") != inc.org:
            return "blocked", "The approval did not come from an approver in this organisation.", "R5-approval"
        return "authorized", f"Allowed by policy and approved by {approval['by']}.", "R5-approval"
    return "authorized", "Allowed by policy: in scope, owned by the subject, reversible.", "R0-default"


def _already_moved(sb, a):
    cur = sb.vault.latest(a.params["cred_id"])
    return sb.dependent_config_fp(a.target) not in (None, a.params["old_fp"]) and cur["v"] > a.params["old_version"]

