.recovery-row + .recovery-row { margin-top: 18px; padding-top: 18px; border-top: 1px solid #333 }
.col { padding: 0 22px } .col:first-child { padding-left: 0 } .col + .col { border-left: 1px solid #444 }
@media (max-width: 760px) { .recovery-row { grid-template-columns: 1fr; gap: 14px } .col, .col:first-child { padding: 0 } .col + .col { border-left: 0; border-top: 1px solid #444; padding-top: 12px } }

/* verification table */
.table-card { padding: 8px 18px; overflow-x: auto }
table { width: 100%; border-collapse: collapse }
td, th { padding: 12px 8px; border-bottom: 1px solid var(--line); text-align: left; vertical-align: top }
tr:last-child td { border-bottom: 0 }
th { font: 700 12px var(--mono); text-transform: uppercase; color: var(--mute) }
@media (max-width: 640px) { td:nth-child(3), th:nth-child(3) { display: none } }

/* timeline */
.timeline { list-style: none; margin: 0; padding: 0; max-height: 420px; overflow-y: auto }
.timeline li { display: grid; grid-template-columns: 96px 1fr; gap: 10px; padding: 7px 0; border-bottom: 1px dashed #d4d4d4 }
.timeline time { color: var(--mute) }
.ev-ok span { color: var(--ok) } .ev-warn span { color: var(--warn) } .ev-bad span { color: var(--bad) }
.ev-warn span::before, .ev-bad span::before { content: "● "; }

/* report + cta + footer */
.report { display: grid; grid-template-columns: 1.2fr 1fr; gap: 28px; align-items: start }
.report .btn-dark { margin-top: 14px }
@media (max-width: 760px) { .report { grid-template-columns: 1fr } }
.cta { display: flex; justify-content: space-between; align-items: center; gap: 24px }
.star-big { flex: none } @media (max-width: 560px) { .star-big { display: none } }
.footer { margin-top: 56px; padding-top: 18px; border-top: 1px solid var(--line); color: var(--mute) }

/* pills */
.pill { display: inline-block; padding: 2px 10px; border-radius: 99px; font: 700 12px var(--mono); white-space: nowrap; border: 1.5px solid currentColor }
.tone-ok { color: var(--ok); background: var(--ok-bg) } .tone-warn { color: var(--warn); background: var(--warn-bg) }
.tone-bad { color: var(--bad); background: var(--bad-bg) } .tone-info { color: var(--info); background: var(--info-bg) }
.tone-mute { color: var(--mute); background: var(--soft) }
.status-card.tone-ok, .status-card.tone-warn, .status-card.tone-bad, .status-card.tone-info, .status-card.tone-mute { color: var(--ink) }
.status-card.tone-ok { background: var(--lime) } .status-card.tone-bad { background: var(--bad-bg) }
.status-card.tone-warn { background: var(--warn-bg) } .status-card.tone-info { background: var(--info-bg) }

/* graph */
.graph-wrap { overflow-x: auto }
.graph-wrap svg { width: 100%; height: auto; display: block; font-family: var(--sans) }
.node { fill: var(--paper); stroke: var(--ink); stroke-width: 1.5 }
.node-ok { fill: var(--lime) } .node-warn { fill: var(--warn-bg) } .node-bad { fill: var(--bad-bg) } .node-mute { fill: var(--soft) }
.node-kind { fill: var(--mute); font: 10.5px var(--mono) } .node-label { fill: var(--ink); font-size: 13px; font-weight: 600 }
.edge-label { fill: var(--mute); font: 10px var(--mono) }
