import hashlib, time
from enum import Enum
from typing import Optional
from pydantic import BaseModel, Field


def fp(v: str) -> str:
    return "fp:" + hashlib.sha256(v.encode()).hexdigest()[:8]


class Status(str, Enum):
    planned = "planned"
    needs_approval = "needs_approval"
    blocked = "blocked"
    authorized = "authorized"
    executing = "executing"
    executed = "executed"
    verified = "verified"
    retry_pending = "retry_pending"
    failed = "failed"
    unknown = "unknown"


S = Status
TRANSITIONS = {
    S.planned: {S.authorized, S.blocked, S.needs_approval},
    S.needs_approval: {S.authorized, S.blocked},
    S.authorized: {S.executing, S.blocked},          # blocked: pre-execution policy re-check failed
    S.executing: {S.executed, S.retry_pending, S.failed, S.unknown, S.verified},
    S.executed: {S.verified, S.failed, S.unknown},
    S.retry_pending: {S.executing, S.failed, S.blocked},
    S.unknown: {S.verified, S.retry_pending, S.failed},
    S.verified: set(),
    S.failed: set(),
    S.blocked: set(),
}


class InvalidTransition(Exception):
    ...


class IncidentStatus(str, Enum):
    investigating = "investigating"
    ready = "ready"
    awaiting_approval = "awaiting_approval"
    remediating = "remediating"
    escalated = "escalated"
    closed_verified = "closed_verified"
    open = "open"


class Incident(BaseModel):
    id: str
    org: str
    created_by: str
    subject: str
    title: str = ""
    severity: str = "high"
    scenario: str = "signature"
    status: str = IncidentStatus.investigating.value
    created_at: float = Field(default_factory=time.time)
    closed_at: Optional[float] = None
    relationships: list[dict] = []     # fingerprints only, never secret values
    graph: dict = {}                   # {nodes: [...], edges: [...]}
    findings: list[dict] = []          # plain-language, evidence-backed
    exposure: str = ""
    ticket: Optional[str] = None


class Action(BaseModel):
    id: str
    incident_id: str
    type: str                 # disable_account | issue_replacement | update_dependent | revoke_credential
    target: str
    params: dict = {}
    depends_on: list[str] = []
    summary: str = ""         # what this does, in plain language
    risk: str = "low"         # low | high (irreversible or production-affecting)
    status: Status = Status.planned
    retries: int = 0
    max_retries: int = 3
    idem_key: str
    policy: dict = {}
    result: dict = {}
    evidence: dict = {}

    def move(self, new: Status):
        if new == self.status:
            return
        if new not in TRANSITIONS[self.status]:
            raise InvalidTransition(f"{self.id}: {self.status.value} -> {new.value}")
        self.status = new


class Condition(BaseModel):
    """A closure condition, defined BEFORE remediation begins."""
    id: str
    description: str
    expected: str
    method: str               # name of an independent observer
    args: dict = {}
    mandatory: bool = True
    result: Optional[bool] = None     # None = not evaluated / inconclusive
    evidence: dict = {}
    evaluated_at: Optional[float] = None


class Principal(BaseModel):
    """An authenticated caller. Always derived server-side from the credential presented."""
    id: str
    org: str
    roles: list[str] = []
    name: str = ""

    def can(self, role: str) -> bool:
        return role in self.roles
"""Deterministic, model-independent authorization. Fails closed.

Rook runs as a least-privilege service principal: it may only perform the action types in
ALLOWED, only against the incident subject's own resources, and irreversible actions need a
human approver from the incident's organisation. Policy is evaluated when the plan is made
and again immediately before each action executes, against live state.
"""

ROOK_PRINCIPAL = "svc-rook"

ALLOWED = {
    "disable_account": {"github", "cloud", "pm"},
    "issue_replacement": {"vault"},
    "update_dependent": {"app", "cloud"},
    "revoke_credential": {"vault"},
    "scrub_exposed_secret": {"github"},
}
NEEDS_APPROVAL = {"revoke_credential"}     # irreversible and production-affecting


def owner_of(sb, a):
    p = a.params
    try:
        if a.type == "disable_account":
            return sb.account_service(p["service"]).owner(a.target)
        if a.type in ("issue_replacement", "revoke_credential"):
            return sb.vault.owner(a.target)
        if a.type in ("update_dependent", "scrub_exposed_secret"):
            return sb.vault.owner(p["cred_id"])
    except KeyError:
        return None


def decide(a, inc, sb, plan, approval=None):
    """Returns (authorized | needs_approval | blocked, reason, rule)."""
    if a.type not in ALLOWED or a.params.get("service") not in ALLOWED[a.type]:
        return "blocked", "This action or service is outside what Rook is allowed to do.", "R1-allowlist"
    owner = owner_of(sb, a)
    if owner is None:
        return "blocked", "Rook could not confirm who owns this resource, so it will not touch it.", "R2-ownership"
    if owner != inc.subject:
        return "blocked", f"This resource belongs to {owner}, not to {inc.subject}.", "R2-ownership"

    if a.type == "update_dependent":
        live = sb.dependents_of_fp(a.params["old_fp"])
        if a.target not in live and not _already_moved(sb, a):
            return "blocked", f"{a.target} does not use this credential.", "R3-dependency"
    if a.type == "revoke_credential":
        live = set(sb.dependents_of_fp(a.params["old_fp"]))
        covered = {x.target for x in plan if x.type == "update_dependent"
                   and x.params.get("cred_id") == a.target and x.status.value != "blocked"}
        if live - covered:
            return ("blocked", "Revoking now would break " + ", ".join(sorted(live - covered))
                    + ", which still use the old key and have no update step.", "R4-safe-order")
        if a.params.get("version") == sb.vault.latest(a.target)["v"]:
            pending = [x for x in plan if x.type == "issue_replacement" and x.target == a.target
                       and x.status.value not in ("blocked", "failed", "verified")]
            if not pending:
                return "blocked", "Refusing to revoke the only working version of this key.", "R4-safe-order"

    if a.type in NEEDS_APPROVAL:
        if approval is None:
            return ("needs_approval", "Revoking a key cannot be undone, so a person with approver "
                    "rights must confirm it.", "R5-approval")
        if "approver" not in approval.get("roles", []) or approval.get("org") != inc.org:
            return "blocked", "The approval did not come from an approver in this organisation.", "R5-approval"
        return "authorized", f"Allowed by policy and approved by {approval['by']}.", "R5-approval"
    return "authorized", "Allowed by policy: in scope, owned by the subject, reversible.", "R0-default"


def may_compensate(sb, a, inc):
    """R7: rolling a dependent back to its previous key is allowed only while that key is still valid
    and the dependent belongs to the incident's credential. It restores a known-good state."""
    if a.type != "update_dependent" or owner_of(sb, a) != inc.subject:
        return False, "Rollback only applies to services of this incident's credential."
    if not sb.vault.authenticate_fp(a.params["old_fp"]):
        return False, "The previous key is no longer valid, so rolling back would not help."
    return True, "Previous key is still valid; restoring the last known-good configuration."


def _already_moved(sb, a):
    cur = sb.vault.latest(a.params["cred_id"])
    return sb.dependent_config_fp(a.target) not in (None, a.params["old_fp"]) and cur["v"] > a.params["old_version"]
import hashlib, json, re, sqlite3, threading, time
from .domain import Action, Condition, Incident, fp

SECRET = re.compile(r"sk_test_SYNTH_[\w-]+")


def redact(obj) -> str:
    return SECRET.sub(lambda m: fp(m.group()), json.dumps(obj, default=str))


class Store:
    def __init__(self, path="rook.db"):
        self.c = sqlite3.connect(path, check_same_thread=False, timeout=10)
        self.lock = threading.RLock()
        self._x("CREATE TABLE IF NOT EXISTS incidents(id TEXT PRIMARY KEY, org TEXT, data TEXT)")
        self._x("CREATE TABLE IF NOT EXISTS actions(id TEXT PRIMARY KEY, incident_id TEXT, seq INTEGER, data TEXT)")
        self._x("CREATE TABLE IF NOT EXISTS conditions(incident_id TEXT, id TEXT, seq INTEGER, data TEXT, PRIMARY KEY(incident_id,id))")
        self._x("CREATE TABLE IF NOT EXISTS audit(n INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, incident_id TEXT, event TEXT, data TEXT)")
        self._x("CREATE TABLE IF NOT EXISTS checkpoints(n INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, incident_id TEXT, label TEXT, data TEXT)")
        self._x("CREATE TABLE IF NOT EXISTS sandbox(id INTEGER PRIMARY KEY, data TEXT)")
        self._x("CREATE TABLE IF NOT EXISTS tool_calls(n INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, incident_id TEXT, action_id TEXT, attempt INTEGER, outcome TEXT, data TEXT)")
        self._x("CREATE TABLE IF NOT EXISTS approvals(n INTEGER PRIMARY KEY AUTOINCREMENT, ts REAL, incident_id TEXT, action_id TEXT, decision TEXT, principal TEXT, data TEXT)")
        self._x("CREATE TABLE IF NOT EXISTS runs(incident_id TEXT PRIMARY KEY, owner TEXT, expires REAL)")
        if "hash" not in [r[1] for r in self._x("PRAGMA table_info(audit)")]:
            self._x("ALTER TABLE audit ADD COLUMN hash TEXT")
        self._x("CREATE TRIGGER IF NOT EXISTS audit_no_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'audit is append-only'); END")
        self._x("CREATE TRIGGER IF NOT EXISTS audit_no_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'audit is append-only'); END")

    def _x(self, sql, args=()):
        with self.lock:
            cur = self.c.execute(sql, args)
            self.c.commit()
            return cur.fetchall()

    # sandbox state
    def load_sandbox(self):
        r = self._x("SELECT data FROM sandbox WHERE id=1")
        return json.loads(r[0][0]) if r else None

    def save_sandbox(self, s):
        self._x("INSERT OR REPLACE INTO sandbox(id,data) VALUES(1,?)", (json.dumps(s),))

    # incidents
    def save_incident(self, inc: Incident):
        self._x("INSERT OR REPLACE INTO incidents VALUES(?,?,?)", (inc.id, inc.org, inc.model_dump_json()))

    def incident(self, iid):
        r = self._x("SELECT data FROM incidents WHERE id=?", (iid,))
        return Incident.model_validate_json(r[0][0]) if r else None

    def incidents(self, org=None):
        rows = self._x("SELECT data FROM incidents WHERE org=?", (org,)) if org else self._x("SELECT data FROM incidents")
        return sorted((Incident.model_validate_json(r[0]) for r in rows), key=lambda i: -i.created_at)

    # actions
    def add_action(self, a: Action, seq: int):
        self._x("INSERT INTO actions VALUES(?,?,?,?)", (a.id, a.incident_id, seq, a.model_dump_json()))

    def save_action(self, a: Action):
        self._x("UPDATE actions SET data=? WHERE id=?", (a.model_dump_json(), a.id))

    def actions(self, iid):
        rows = self._x("SELECT data FROM actions WHERE incident_id=? ORDER BY seq", (iid,))
        return [Action.model_validate_json(r[0]) for r in rows]

    # closure conditions
    def save_conditions(self, iid, conds):
        for i, c in enumerate(conds):
            self._x("INSERT OR REPLACE INTO conditions(incident_id,id,seq,data) VALUES(?,?,?,?)",
                    (iid, c.id, i, c.model_dump_json()))

    def conditions(self, iid):
        rows = self._x("SELECT data FROM conditions WHERE incident_id=? ORDER BY seq", (iid,))
        return [Condition.model_validate_json(r[0]) for r in rows]

    # audit + checkpoints (secrets redacted before write)
    @staticmethod
    def _chain(prev, ts, iid, event, data):
        return hashlib.sha256(json.dumps([prev, repr(ts), iid, event, data]).encode()).hexdigest()

