"""Rook HTTP API.

    uvicorn rook.api:create_app --factory --port 8000

Every route except /api/health requires `Authorization: Bearer <token>`. The caller's identity,
organisation and roles come only from that token (server-side lookup); request bodies cannot
name an owner, org or approver. Incidents are scoped to the caller's organisation, and an
incident from another organisation is indistinguishable from one that does not exist.

The adapters behind this API are sandboxed mocks with synthetic credentials.
"""
import hashlib, hmac, json, os, pathlib, re, threading, time
from contextlib import asynccontextmanager
from typing import Literal, Optional
from fastapi import Depends, FastAPI, HTTPException, Request
from fastapi.responses import JSONResponse, PlainTextResponse
from fastapi.staticfiles import StaticFiles
from pydantic import BaseModel, ConfigDict, Field
from . import obs
from .domain import Principal
from .engine import Engine, RunInProgress, evidence_pack
from .sandbox import SCENARIOS, Sandbox
from .store import Store

MAX_BODY = 8 * 1024
INCIDENT_ID = re.compile(r"^inc-[0-9a-f]{8}$")
ACTION_ID = re.compile(r"^inc-[0-9a-f]{8}-a\d{1,3}$")

# Local demo identities. Replace with ROOK_TOKENS (JSON {token: principal}) anywhere shared.
DEMO_TOKENS = {
    "demo-analyst-token": {"id": "u-sam", "name": "Sam (security analyst)", "org": "acme", "roles": ["analyst"]},
    "demo-approver-token": {"id": "u-priya", "name": "Priya (security lead)", "org": "acme",
                            "roles": ["analyst", "approver"]},
    "demo-viewer-token": {"id": "u-lee", "name": "Lee (read only)", "org": "acme", "roles": ["viewer"]},
    "demo-other-org-token": {"id": "u-eve", "name": "Eve (other company)", "org": "globex",
                             "roles": ["analyst", "approver"]},
}

ScenarioName = Literal[tuple(SCENARIOS)]


class CreateIncident(BaseModel):
    model_config = ConfigDict(extra="forbid")
    scenario: ScenarioName = "signature"


class RejectBody(BaseModel):
    model_config = ConfigDict(extra="forbid")
    note: str = Field(default="", max_length=500)


class Empty(BaseModel):
    model_config = ConfigDict(extra="forbid")


def env(name, default=None):
    """ROOK_<name>, falling back to the earlier KEYWARDEN_<name> spelling."""
    return os.getenv(f"ROOK_{name}", os.getenv(f"KEYWARDEN_{name}", default))


def _h(token: str) -> str:
    return hashlib.sha256(token.encode()).hexdigest()


def load_tokens():
    raw = env("TOKENS")
    if raw:
        return json.loads(raw)
    if env("DEMO_TOKENS", "1") == "1":
        return DEMO_TOKENS
    return {}


def create_app(db_path=None, tokens=None, step_delay=None, background=True, rate_limit=30, read_rate_limit=900):
    db_path = db_path or env("DB", "rook.db")
    step_delay = float(env("STEP_DELAY", "0.6")) if step_delay is None else step_delay
    principals = {_h(t): Principal(**p) for t, p in (tokens if tokens is not None else load_tokens()).items()}
    store = Store(db_path)
    sb = Sandbox(store)
    engines: dict[str, Engine] = {}
    sandbox_lock = threading.Lock()
    hits: dict[str, list[float]] = {}

    @asynccontextmanager
    async def lifespan(app):
        obs.init_neatlogs(workflow_name="rook-api")
        yield
        obs.shutdown()

    app = FastAPI(title="Rook", lifespan=lifespan, docs_url="/api/docs", openapi_url="/api/openapi.json")
    app.state.store, app.state.sandbox = store, sb

    # ---------------------------------------------------------------- middleware + errors
    @app.middleware("http")
    async def guard(request: Request, call_next):
        if request.method in ("POST", "PUT", "PATCH"):
            n = request.headers.get("content-length")
            if n is not None and (not n.isdigit() or int(n) > MAX_BODY):
                return JSONResponse({"detail": "request body too large"}, status_code=413)
            body = await request.body()
            if len(body) > MAX_BODY:
                return JSONResponse({"detail": "request body too large"}, status_code=413)
        resp = await call_next(request)
        resp.headers["X-Content-Type-Options"] = "nosniff"
        resp.headers["Cache-Control"] = "no-store"
        resp.headers["Referrer-Policy"] = "no-referrer"
        return resp

    @app.exception_handler(Exception)
    async def unhandled(request, exc):           # never leak internals or stack traces
        return JSONResponse({"detail": "internal error"}, status_code=500)

    # ---------------------------------------------------------------- auth
    def principal(request: Request) -> Principal:
        auth = request.headers.get("authorization", "")
        if not auth.lower().startswith("bearer "):
            raise HTTPException(401, "missing bearer token", headers={"WWW-Authenticate": "Bearer"})
        digest = _h(auth[7:].strip())
        match = next((p for h, p in principals.items() if hmac.compare_digest(h, digest)), None)
        if match is None:
            raise HTTPException(401, "invalid token", headers={"WWW-Authenticate": "Bearer"})
        return match

    def limited(request: Request, p: Principal = Depends(principal)) -> Principal:
        """Per-principal sliding window: tight for changes, loose for reads (the dashboard polls)."""
        write = request.method != "GET"
        key, limit = (f"w:{p.id}", rate_limit) if write else (f"r:{p.id}", read_rate_limit)
        now = time.time()
        window = [t for t in hits.get(key, []) if now - t < 60]
        if len(window) >= limit:
            raise HTTPException(429, "too many requests")
        hits[key] = window + [now]
        return p

    def need(p: Principal, role: str):
        if not p.can(role):
            raise HTTPException(403, f"requires the {role} role")

    def owned_incident(iid: str, p: Principal):
        """Object-level authorization: the incident must belong to the caller's organisation."""
        if not INCIDENT_ID.match(iid):
            raise HTTPException(404, "incident not found")
        inc = store.incident(iid)
        if inc is None or inc.org != p.org:
            raise HTTPException(404, "incident not found")
        return inc

    def check_action_id(iid, aid):
        if not ACTION_ID.match(aid) or not aid.startswith(iid + "-"):
            raise HTTPException(404, "action not found")

    def start_run(iid):
        eng = Engine(store, sb, step_delay=step_delay)
        engines[iid] = eng

        def work():
            try:
                eng.run(iid)
            except RunInProgress:
                pass
        if background:
            threading.Thread(target=work, daemon=True).start()
        else:
            work()

    # ---------------------------------------------------------------- routes
    @app.get("/api/health")
    def health():
        return {"ok": True, "adapters": "sandboxed mock integrations, synthetic credentials only"}

    @app.get("/api/me")
    def me(p: Principal = Depends(limited)):
        return p.model_dump()

    @app.get("/api/scenarios")
    def scenarios(p: Principal = Depends(limited)):
        return [{"name": k, "description": v[0]} for k, v in SCENARIOS.items()]

    @app.get("/api/incidents")
    def list_incidents(p: Principal = Depends(limited)):
        return [{"id": i.id, "title": i.title, "status": i.status, "severity": i.severity,
                 "scenario": i.scenario, "created_at": i.created_at, "created_by": i.created_by}
                for i in store.incidents(org=p.org)]

    @app.post("/api/incidents", status_code=201)
    def create(body: Optional[CreateIncident] = None, p: Principal = Depends(limited)):
        need(p, "analyst")
        body = body or CreateIncident()
        with sandbox_lock:
            if any(store.run_active(i.id) for i in store.incidents()):
                raise HTTPException(409, "another incident is running in the sandbox; wait for it to finish")
            sb.reset(scenario=body.scenario)
            inc = Engine(store, sb).start(org=p.org, created_by=p.id, scenario=body.scenario)
        return {"id": inc.id, "status": inc.status, "title": inc.title}

    @app.get("/api/incidents/{iid}")
    def get(iid: str, p: Principal = Depends(limited)):
        owned_incident(iid, p)
        rep = Engine(store, sb).report(iid)
        return {"report": rep, "audit": store.audit_events(iid), "checkpoints": store.checkpoints(iid),
                "running": store.run_active(iid),
                "can": {"run": p.can("analyst"), "approve": p.can("approver")}}

    @app.get("/api/incidents/{iid}/evidence")
    def evidence(iid: str, p: Principal = Depends(limited)):
        owned_incident(iid, p)
        md = evidence_pack(Engine(store, sb).report(iid), store.audit_events(iid), store.verify_chain())
        return PlainTextResponse(md, media_type="text/markdown",
                                 headers={"Content-Disposition": f'attachment; filename="{iid}-evidence.md"'})

    @app.get("/api/incidents/{iid}/events")
    def events(iid: str, after: int = 0, p: Principal = Depends(limited)):
        owned_incident(iid, p)
        return [e for e in store.audit_events(iid) if e["n"] > after]

    @app.post("/api/incidents/{iid}/run", status_code=202)
    def run(iid: str, body: Optional[Empty] = None, p: Principal = Depends(limited)):
        need(p, "analyst")
        inc = owned_incident(iid, p)
        if store.run_active(iid):
            raise HTTPException(409, "already running")
        if inc.status == "closed_verified":
            raise HTTPException(409, "incident is already closed")
        store.audit(iid, "run_requested", {"by": p.id})
        start_run(iid)
        return {"started": iid}

    @app.post("/api/incidents/{iid}/cancel", status_code=202)
    def cancel(iid: str, body: Optional[Empty] = None, p: Principal = Depends(limited)):
        need(p, "analyst")
        owned_incident(iid, p)
        if iid in engines:
            engines[iid].cancel()
        store.audit(iid, "cancel_requested", {"by": p.id})
        return {"cancelled": iid}

    @app.post("/api/incidents/{iid}/actions/{aid}/approve")
    def approve(iid: str, aid: str, body: Optional[Empty] = None, p: Principal = Depends(limited)):
        need(p, "approver")
        owned_incident(iid, p)
        check_action_id(iid, aid)
        try:
            a = Engine(store, sb).approve(iid, aid, p)
        except KeyError:
            raise HTTPException(404, "action not found")
        except ValueError as e:
            raise HTTPException(409, str(e))
        except PermissionError as e:
            raise HTTPException(403, str(e))
        if not store.run_active(iid):
            start_run(iid)
        return {"action": a.id, "status": a.status.value, "policy": a.policy}

    @app.post("/api/incidents/{iid}/actions/{aid}/reject")
    def reject(iid: str, aid: str, body: Optional[RejectBody] = None, p: Principal = Depends(limited)):
        need(p, "approver")
        owned_incident(iid, p)
        check_action_id(iid, aid)
        try:
            a = Engine(store, sb).reject(iid, aid, p, (body or RejectBody()).note)
        except KeyError:
            raise HTTPException(404, "action not found")
        except ValueError as e:
            raise HTTPException(409, str(e))
        if not store.run_active(iid):
            start_run(iid)
        return {"action": a.id, "status": a.status.value}

    # Single-container deploys: serve the statically exported dashboard from the same origin.
    static = pathlib.Path(env("STATIC", pathlib.Path(__file__).parent.parent / "web" / "out"))
    if static.is_dir():
        app.mount("/", StaticFiles(directory=static, html=True), name="dashboard")
    return app
"""Run one sandboxed incident end to end and print what happened.

    python -m rook.demo                       # signature scenario (transient failure + recovery)
    python -m rook.demo --scenario persistent # Rook escalates instead of claiming success
    NEATLOGS_API_KEY=... python -m rook.demo  # same, with traces exported to neatlogs

The demo also probes every dependent application's health after each workflow step, so a trace
shows whether remediation caused an outage for the services that rely on the credential.
"""
import argparse, json, os, tempfile, time
from . import obs
from .domain import Principal
from .engine import Engine
from .sandbox import SCENARIOS, Sandbox
from .store import Store

# The demo plays the human approver from the command line. In the app, approval comes from an
# authenticated user with the approver role.
DEMO_APPROVER = Principal(id="demo-approver", org="acme", roles=["approver"], name="Demo approver")


def dependents(sb):
    """Services that relied on the leaked key when the incident began."""
    return ["app:billing-app", "cloud:payments-worker"]


def main(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument("--scenario", default="signature", choices=sorted(SCENARIOS))
    ap.add_argument("--no-approve", action="store_true", help="stop when approval is required")
    ap.add_argument("--label", default=os.getenv("ROOK_DEMO_LABEL", "dev"))
    args = ap.parse_args(argv)

    exporting = obs.init_neatlogs(workflow_name="rook-incident-response")
    db = os.path.join(tempfile.mkdtemp(), "demo.db")
    st = Store(db)
    sb = Sandbox(st, scenario=args.scenario)
    probes = {"steps": 0, "outage_steps": 0, "unhealthy": {}}

    real_checkpoint = st.checkpoint

    def checkpoint(iid, label, data):        # probe dependents after every persisted step
        real_checkpoint(iid, label, data)
        if label != "step":
            return
        probes["steps"] += 1
        with obs.span("probe.dependent_health", incident=iid, step=probes["steps"]) as s:
            bad = [a for a in dependents(sb) if not sb.health(a)]
            s.set(unhealthy_dependents=len(bad), healthy=not bad)
        if bad:
            probes["outage_steps"] += 1
            for a in bad:
                probes["unhealthy"][a] = probes["unhealthy"].get(a, 0) + 1
    st.checkpoint = checkpoint

    t0 = time.time()
    with obs.span("demo.incident", scenario=args.scenario, label=args.label) as root:
        eng = Engine(st, sb, sleep=lambda s: None)
        inc = eng.start(scenario=args.scenario)
        rep = eng.run(inc.id)
        if rep["status"] == "awaiting_approval" and not args.no_approve:
            for a in [x for x in st.actions(inc.id) if x.status.value == "needs_approval"]:
                eng.approve(inc.id, a.id, DEMO_APPROVER)
            rep = eng.run(inc.id)
        root.set(incident=inc.id, status=rep["status"], tool_calls=rep["metrics"]["tool_calls"],
                 dependent_outage_steps=probes["outage_steps"])
    summary = {
        "label": args.label, "scenario": args.scenario, "incident": inc.id, "status": rep["status"],
        "duration_ms": round((time.time() - t0) * 1000, 1),
        "summary": rep["summary"],
        "tool_calls": rep["metrics"]["tool_calls"], "failed_tool_calls": rep["metrics"]["failed_tool_calls"],
        "checkpoints": rep["metrics"]["checkpoints"], "audit_events": rep["metrics"]["audit_events"],
        "conditions_passed": f"{sum(c['result'] is True for c in rep['conditions'])}/{len(rep['conditions'])}",
        "workflow_steps": probes["steps"], "dependent_outage_steps": probes["outage_steps"],
        "unhealthy_dependents": probes["unhealthy"],
        "retries": {a["id"]: a["retries"] for a in rep["actions"] if a["retries"]},
        "neatlogs_export": exporting,
    }
    if exporting:
        obs.flush()
        summary["neatlogs_delivery"] = {k: v for k, v in obs.delivery().items()
                                        if k.startswith("span_") and isinstance(v, int)}
        obs.shutdown()
    print(json.dumps(summary, indent=2))
    return summary


if __name__ == "__main__":
    main()

'use client'
import { useCallback, useEffect, useRef, useState } from 'react'
import Graph from './components/Graph'
import {
  ACTION_LABEL, ApiError, IDENTITIES, INCIDENT_STATE, actionState, api, eventText, eventTone, time,
} from './lib'

const Pill = ({ tone, children }: { tone: string; children: React.ReactNode }) =>
  <span className={`pill tone-${tone}`}>{children}</span>

function useIdentity() {
  const [key, setKey] = useState('analyst')
  useEffect(() => {
    try { const k = sessionStorage.getItem('kw-identity'); if (k) setKey(k) } catch { /* storage unavailable */ }
  }, [])
  const choose = (k: string) => { setKey(k); try { sessionStorage.setItem('kw-identity', k) } catch { /* ignore */ } }
  return [IDENTITIES.find((i) => i.key === key) || IDENTITIES[0], choose] as const
}

function liveState(actions: any[], graph: any): Record<string, string> {
  const m: Record<string, string> = {}
  for (const a of actions) {
    const ok = a.status === 'verified', bad = a.status === 'failed'
    if (a.type === 'disable_account') m[`${a.service}:${a.target}`] = ok ? 'disabled' : bad ? 'disable failed' : m[`${a.service}:${a.target}`]
    if (a.type === 'update_dependent') m[a.target] = ok ? 'moved to new key' : bad ? 'update failed' : m[a.target]
    if (a.type === 'issue_replacement' && ok) m[a.target] = 'replacement issued'
    if (a.type === 'revoke_credential') m[a.target] = ok ? 'revoked' : bad ? 'revoke failed' : m[a.target]
    if (a.type === 'revoke_credential' && ok) (graph?.nodes || []).filter((n: any) => n.kind === 'repo').forEach((n: any) => { m[n.id] = 'leaked key is dead' })
    if (a.type === 'scrub_exposed_secret' && ok) m[`repo:${a.target}`] = 'key removed from file'
    if (a.type === 'update_dependent' && a.result?.rolled_back) m[a.target] = 'rolled back · healthy'
  }
  return Object.fromEntries(Object.entries(m).filter(([, v]) => v))
}

export default function Page() {
  const [who, setWho] = useIdentity()
  const [me, setMe] = useState<any>(null)
  const [scenarios, setScenarios] = useState<any[]>([])
  const [scenario, setScenario] = useState('signature')
  const [list, setList] = useState<any[] | null>(null)
  const [id, setId] = useState<string | null>(null)
  const [d, setD] = useState<any>(null)
  const [err, setErr] = useState<string | null>(null)
  const [busy, setBusy] = useState(false)
  const [notice, setNotice] = useState<string | null>(null)
  const timer = useRef<any>(null)
  const tl = useRef<HTMLOListElement>(null)
  const nEvents = d?.audit?.length || 0
  useEffect(() => { if (tl.current) tl.current.scrollTop = tl.current.scrollHeight }, [nEvents])

  const loadList = useCallback(async () => {
    try {
      const [m, s, l] = await Promise.all([api(who.token, '/me'), api(who.token, '/scenarios'), api(who.token, '/incidents')])
      setMe(m); setScenarios(s); setList(l); setErr(null)
    } catch (e: any) { setErr(e.message); setList([]) }
  }, [who.token])

  useEffect(() => { setD(null); setId(null); loadList() }, [loadList])

  const loadIncident = useCallback(async (iid: string) => {
    try {
      const x = await api(who.token, `/incidents/${iid}`)
      setD((prev: any) => {
        if (!prev || prev.report.status !== x.report.status || prev.running !== x.running) loadList()
        return x
      })
      setErr(null)
      return x
    } catch (e: any) {
      if (e instanceof ApiError && e.status === 404) { setD(null); setId(null); setNotice('That incident is not visible to this identity.') }
      else setErr(e.message)
      return null
    }
  }, [who.token, loadList])

  // Poll while the backend reports a run in progress; stop once it settles.
  useEffect(() => {
    if (!id) return
    let stop = false
    const tick = async () => {
      const x = await loadIncident(id)
      if (stop) return
      const settled = x && !x.running && ['closed_verified', 'escalated', 'awaiting_approval', 'ready'].includes(x.report.status)
      timer.current = setTimeout(tick, settled ? 4000 : 700)
    }
    tick()
    return () => { stop = true; clearTimeout(timer.current) }
  }, [id, loadIncident])

  async function act(fn: () => Promise<any>, ok?: string) {
    setBusy(true); setNotice(null)
    try { await fn(); if (ok) setNotice(ok); if (id) await loadIncident(id); await loadList() } catch (e: any) { setNotice(e.message) } finally { setBusy(false) }
  }

  async function create() {
    await act(async () => {
      const inc = await api(who.token, '/incidents', { scenario })
      setId(inc.id)
    })
  }

  const R = d?.report
  const state = R ? INCIDENT_STATE[R.status] || INCIDENT_STATE.open : null
  const pending = R?.actions.filter((a: any) => a.status === 'needs_approval') || []

  const isAnalyst = !!me?.roles.includes('analyst')
  const isApprover = !!me?.roles.includes('approver')

  return (
    <div className="page">
      <div className="frame">
        <nav className="nav" aria-label="Main">
          <a className="brand" href="#top"><Star /> Rook</a>
          <div className="nav-links">
            <a href="#incident">Incident</a>
            <a href="#plan">Plan</a>
            <a href="#verify">Verification</a>
            <a href="#timeline">Timeline</a>
          </div>
          <label className="who">
            <span className="sr-only">Signed in as (demo identity)</span>
            <select id="who" value={who.key} onChange={(e) => setWho(e.target.value)}>
              {IDENTITIES.map((i) => <option key={i.key} value={i.key}>{i.label}</option>)}
            </select>
          </label>
        </nav>

        <header className="hero" id="top">
          <div className="hero-copy">
            <h1>Close credential incidents only when they are actually closed.</h1>
            <p>Rook investigates a leaked key, fixes it in a safe order, recovers when a step fails and closes the incident only after independent checks pass.</p>
            <div className="hero-form">
              <label htmlFor="scenario" className="mono small">Sandbox scenario</label>
              <div className="row">
                <select id="scenario" value={scenario} onChange={(e) => setScenario(e.target.value)}>
                  {scenarios.map((s) => <option key={s.name} value={s.name}>{s.name.replace(/_/g, ' ')}</option>)}
                </select>
                <button className="btn-dark" disabled={busy || !isAnalyst} onClick={create}>Investigate offboarded contractor</button>
              </div>
              <p className="small muted">{scenarios.find((s) => s.name === scenario)?.description}</p>
              {me && !isAnalyst && <p className="small muted">{who.label} cannot start incidents.</p>}
            </div>
          </div>
          <HeroArt />
        </header>

        <p className="strip mono" role="note">
          <span>sandbox</span><span>synthetic keys</span><span>org {me?.org || '…'}</span><span>{me ? me.roles.join(' + ') : 'loading'}</span>
        </p>

        {err && (
          <div className="card alert" role="alert">
            <b>Something went wrong.</b> {err}{' '}
            <button className="btn-outline" onClick={() => (id ? loadIncident(id) : loadList())}>Retry</button>
          </div>
        )}
        {notice && <div className="card notice" role="status">{notice}</div>}

        <section className="section">
          <SectionTitle label="Incidents" text="Each run is stored with its plan, checkpoints and audit trail." />
          {list === null && <p className="muted">Loading…</p>}
          {list?.length === 0 && <p className="muted">No incidents yet for this organisation. Start one above.</p>}
          <ul className="chips">
            {list?.map((i) => {
              const st = INCIDENT_STATE[i.status] || INCIDENT_STATE.open
              return (
                <li key={i.id}>
                  <button className={`chip ${i.id === id ? 'sel' : ''}`} aria-pressed={i.id === id}
                    onClick={() => { setNotice(null); setId(i.id) }}>
                    <span className="mono small">{time(i.created_at)}</span>
                    <b>{i.scenario.replace(/_/g, ' ')}</b>
                    <Pill tone={st.tone}>{st.label}</Pill>
                  </button>
                </li>
              )
            })}
          </ul>
        </section>

        <div aria-live="polite">
          {id && !R && !err && <p className="muted section">Loading incident…</p>}

          {R && state && (<>
            {/* Overview */}
            <section className="section" id="incident">
              <div className="overview">
                <div>
                  <p className="mono small muted">{R.incident.id} · severity {R.incident.severity} · ticket {R.incident.ticket || 'none'}</p>
                  <h2 className="h2">{R.incident.title}</h2>
                  <p className="lead">{R.summary}</p>
                  <div className="row">
                    {isAnalyst && !d.running && ['ready', 'escalated', 'open', 'awaiting_approval'].includes(R.status) && (
                      <button className="btn-dark" disabled={busy} onClick={() => act(() => api(who.token, `/incidents/${id}/run`, {}), 'Run started.')}>
                        {R.status === 'ready' ? 'Run plan' : 'Run again'}
                      </button>
                    )}
                    {isAnalyst && d.running && (
                      <button className="btn-outline" disabled={busy} onClick={() => act(() => api(who.token, `/incidents/${id}/cancel`, {}), 'Cancel requested.')}>Cancel run</button>
                    )}
                  </div>
                </div>
                <div className={`status-card tone-${state.tone}`}>
                  <span className="mono small">status</span>
                  <b>{d.running ? 'Running' : state.label}</b>
                  <span className="small">{d.running ? 'Rook is making and checking changes.' : state.text}</span>
                </div>
              </div>
              <div className="stats">
                <Stat dark={false} label="Actions verified" value={`${R.actions.filter((a: any) => a.status === 'verified').length}/${R.actions.length}`} />
                <Stat dark label="Closure checks passing" value={`${R.conditions.filter((c: any) => c.result === true).length}/${R.conditions.length}`} />
                <Stat dark label="Failed tool calls" value={R.metrics.failed_tool_calls} />
                <Stat dark={false} label="Old key dead after" value={R.metrics.seconds_until_old_key_dead != null ? `${R.metrics.seconds_until_old_key_dead}s` : '—'} />
              </div>
            </section>

            {/* Approval */}
            {pending.map((a: any) => {
              const ready = a.depends_on.every((x: string) => R.actions.find((y: any) => y.id === x)?.status === 'verified')
              return (
                <section key={a.id} className="section">
                  <div className="approval" aria-labelledby={`ap-${a.id}`}>
                    <div>
                      <h2 id={`ap-${a.id}`} className="h3"><mark>{ready ? 'Approval needed now' : 'Approval will be needed'}</mark></h2>
                      <p className="lead">{a.summary}</p>
                      {!ready && <p className="small">Rook pauses here once the earlier steps are verified. An approver can confirm in advance; policy is re-checked just before it runs.</p>}
                      <ul className="facts">
                        <li><b>Why approval:</b> {a.policy.reason}</li>
                        <li><b>Can it be undone?</b> No. The old key stops working everywhere, permanently.</li>
                        <li><b>Safety check:</b> runs only after steps {a.depends_on.map((x: string) => R.actions.findIndex((y: any) => y.id === x) + 1).join(', ')} are verified.</li>
                      </ul>
                    </div>
                    <div className="approval-actions">
                      {isApprover ? (<>
                        <button className="btn-lime" disabled={busy} onClick={() => act(() => api(who.token, `/incidents/${id}/actions/${a.id}/approve`, {}), 'Approved. Rook is continuing.')}>Approve revocation</button>
                        <button className="btn-ghost" disabled={busy} onClick={() => act(() => api(who.token, `/incidents/${id}/actions/${a.id}/reject`, { note: 'Rejected from dashboard' }), 'Rejected. The incident will be escalated.')}>Reject</button>
                      </>) : <p className="small">Waiting for someone with the approver role. Switch to “Priya” to approve.</p>}
                    </div>
                  </div>
                </section>
              )
            })}

            {/* Graph + findings */}
            <section className="section">
              <SectionTitle label="Who and what is connected" text="Discovered by Rook, with each node updated as actions are verified." />
              <div className="card"><Graph graph={R.incident.graph} live={liveState(R.actions, R.incident.graph)} /></div>
            </section>

            <section className="section">
              <SectionTitle label="Findings" text="What the evidence shows, before anything is changed." />
              <ul className="findings">
                {R.incident.findings.map((f: any, i: number) => (
                  <li key={i} className="card finding">
                    <Pill tone={f.severity === 'high' ? 'bad' : f.severity === 'medium' ? 'warn' : 'mute'}>{f.severity}</Pill>
                    <span>{f.text}</span>
                  </li>
                ))}
              </ul>
            </section>

            {/* Plan */}
            <section className="section" id="plan">
              <SectionTitle label="Plan" text="Steps run in this order. Each one is checked against live state before the next can start." />
              <ol className="plan">
                {R.actions.map((a: any, i: number) => {
                  const s = actionState(a)
                  const dark = a.risk === 'high'
                  return (
                    <li key={a.id} className={`step ${dark ? 'step-dark' : ''}`}>
                      <div className="step-head">
                        <span className="num mono">{String(i + 1).padStart(2, '0')}</span>
                        <h3 className="h4"><mark>{ACTION_LABEL[a.type] || a.type}</mark></h3>
                        <Pill tone={s.tone}>{s.label}</Pill>
                        {a.risk === 'high' && <Pill tone="bad">irreversible</Pill>}
                      </div>
                      <p className="mono small target">{a.target}</p>
                      <p>{a.summary}</p>
                      <p className="small dim">
                        Policy {a.policy.rule}: {a.policy.reason}
                        {a.depends_on.length > 0 && <> · after step {a.depends_on.map((x: string) => R.actions.findIndex((y: any) => y.id === x) + 1).join(', ')}</>}
                        {a.retries > 0 && <> · {a.retries} failed attempt{a.retries > 1 ? 's' : ''}</>}
                      </p>
                      {a.result?.error && <p className="small err-text">{a.result.error}</p>}
                      {(Object.keys(a.evidence || {}).length > 0) && (
                        <details><summary><Arrow /> Verification evidence</summary><pre>{JSON.stringify(a.evidence, null, 2)}</pre></details>
                      )}
                    </li>
                  )
                })}
              </ol>
            </section>

            <Recovery R={R} audit={d.audit} checkpoints={d.checkpoints} />

            {/* Verification */}
            <section className="section" id="verify">
              <SectionTitle label="Verification" text="Fixed before any change was made, and measured by probing live state, never by trusting a tool’s reply." />
              <div className="card table-card">
                <table>
                  <thead><tr><th scope="col">Check</th><th scope="col">Result</th><th scope="col">Evidence</th></tr></thead>
                  <tbody>
                    {R.conditions.map((c: any) => {
                      const r = c.result === true ? ['ok', 'Pass'] : c.result === false ? ['bad', 'Fail'] : ['warn', c.evaluated_at ? 'Inconclusive' : 'Not checked yet']
                      return (
                        <tr key={c.id}>
                          <td>{c.description}<div className="small muted">{c.expected}</div></td>
                          <td><Pill tone={r[0]}>{r[1]}</Pill></td>
                          <td><code className="small">{Object.entries(c.evidence || {}).map(([k, v]) => `${k}: ${JSON.stringify(v)}`).join(' · ') || '—'}</code></td>
                        </tr>
                      )
                    })}
                  </tbody>
                </table>
              </div>
            </section>

            {/* Timeline */}
            <section className="section" id="timeline">
              <SectionTitle label="Timeline" text={`${d.audit.length} audit events, append-only, straight from the backend.`} />
              <div className="soft">
                <ol className="timeline" ref={tl} tabIndex={0} aria-label="Audit events, oldest first">
                  {d.audit.map((e: any) => (
                    <li key={e.n} className={`ev-${eventTone(e.event)}`}>
                      <time className="mono small">{time(e.ts)}</time><span>{eventText(e)}</span>
                    </li>
                  ))}
                </ol>
              </div>
            </section>

            {/* Report */}
            <section className="section">
              <SectionTitle label="Report" text="What a reviewer needs to sign off, or to pick up an escalation." />
              <div className="report">
                <div>
                  <p className="lead">{R.summary}</p>
                  {R.closure_blocked_reason && <p className="small"><b>Why it is not closed:</b> {R.closure_blocked_reason}</p>}
                  {R.approvals.length > 0 && <p className="small">Approvals: {R.approvals.map((a: any) => `${a.decision} by ${a.by} at ${time(a.ts)}`).join('; ')}</p>}
                  {R.follow_ups.length > 0 && (<>
                    <h3 className="h4" style={{ marginTop: 16 }}><mark>Left for a person</mark></h3>
                    <ul className="facts">{R.follow_ups.map((f: string, i: number) => <li key={i}>→ {f}</li>)}</ul>
                  </>)}
                  <div className="row">
                    <button className="btn-dark" disabled={busy} onClick={() => act(async () => {
                      const r = await fetch(`/api/incidents/${id}/evidence`, { headers: { Authorization: `Bearer ${who.token}` } })
                      if (!r.ok) throw new Error('Could not build the evidence pack.')
                      const u = URL.createObjectURL(await r.blob()); const el = document.createElement('a')
                      el.href = u; el.download = `${R.incident.id}-evidence.md`; el.click(); URL.revokeObjectURL(u)
                    })}>Download evidence pack (.md)</button>
                    <button className="btn-outline" onClick={() => {
                      const blob = new Blob([JSON.stringify({ report: R, audit: d.audit }, null, 2)], { type: 'application/json' })
                      const u = URL.createObjectURL(blob); const el = document.createElement('a')
                      el.href = u; el.download = `${R.incident.id}-report.json`; el.click(); URL.revokeObjectURL(u)
                    }}>Raw JSON</button>
                  </div>
                  <p className="small muted">Audit log is hash-chained: {R.invariants.audit_chain_intact ? 'chain verified intact' : 'CHAIN BROKEN'} · {R.metrics.checkpoints} checkpoints.</p>
                </div>
                <ul className="facts invariants">
                  {Object.entries(R.invariants).map(([k, v]) => (
                    <li key={k}><Pill tone={v ? 'ok' : 'bad'}>{v ? 'yes' : 'no'}</Pill> {k.replace(/_/g, ' ')}</li>
                  ))}
                </ul>
              </div>
            </section>
          </>)}

          {!id && !err && (
            <section className="section">
              <div className="soft cta">
                <div>
                  <h2 className="h3">Try the signature scenario</h2>
                  <p>billing-app’s config API fails once mid-fix. Watch Rook save a checkpoint, inspect what really happened, retry safely and still close with evidence.</p>
                </div>
                <Star big />
              </div>
            </section>
          )}
        </div>

        <footer className="footer mono small">Rook · built by Keywarden · sandboxed mock integrations, synthetic credentials only</footer>
      </div>
    </div>
  )
}

function SectionTitle({ label, text }: { label: string; text: string }) {
  return (
    <div className="section-title">
      <h2><mark>{label}</mark></h2>
      <p className="small">{text}</p>
    </div>
  )
}

function Stat({ label, value, dark }: { label: string; value: any; dark: boolean }) {
  return (
    <div className={`stat ${dark ? 'stat-dark' : ''}`}>
      <span className="small"><mark>{label}</mark></span>
      <b>{value}</b>
    </div>
  )
}

const Arrow = () => (
  <svg className="arrow" viewBox="0 0 24 24" width="22" height="22" aria-hidden="true">
    <circle cx="12" cy="12" r="11" fill="currentColor" />
    <path d="M8 16 L16 8 M10 8 H16 V14" stroke="var(--lime)" strokeWidth="2" fill="none" strokeLinecap="round" />
  </svg>
)

const Star = ({ big }: { big?: boolean }) => (
  <svg viewBox="0 0 24 24" width={big ? 96 : 20} height={big ? 96 : 20} aria-hidden="true" className={big ? 'star-big' : ''}>
    <path d="M12 0 C13 8 16 11 24 12 C16 13 13 16 12 24 C11 16 8 13 0 12 C8 11 11 8 12 0Z" fill={big ? 'var(--lime)' : 'currentColor'} stroke={big ? 'var(--ink)' : 'none'} />
  </svg>
)

function HeroArt() {
  return (
    <svg className="hero-art" viewBox="0 0 320 240" role="img" aria-label="A key inside orbit rings, with check marks">
      <ellipse cx="170" cy="130" rx="130" ry="46" fill="none" stroke="var(--ink)" strokeWidth="1.5" transform="rotate(-12 170 130)" />
